// Function to find the nth number in the sequence
int findNumberInSequence(int n) {
    // Base cases
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // Initialize the first three numbers of the sequence
    int a = 0, b = -1, c = -1, d = 0;

    // Calculate the next number in the sequence
    for (int i = 3; i <= n; i++) {
        d = a + b + c;
        // Shift the last three numbers to the left
        a = b;
        b = c;
        c = d;
    }

    return d;
}

int main() {
    int n;
    cout << "Enter the value of n: ";
    cin >> n;

    // Check if the entered value is non-negative
    if (n < 0) {
