def find_kth_smallest(list1: List[int], list2: List[int], k: int) -> int:
    """
    Finds the kth smallest element in the union of two sorted lists.

    Args:
    list1: A sorted list of integers.
    list2: Another sorted list of integers.
    k: The kth position (1-indexed) to find the smallest element for.

    Returns:
    The kth smallest element in the union of the two lists.
    """
    def find_kth(nums1, start1, nums2, start2, k):
        if start1 >= len(nums1):
            return nums2[start2 + k - 1]
        if start2 >= len(nums2):
            return nums1[start1 + k - 1]
        if k == 1:
            return min(nums1[start1], nums2[start2])

        mid1 = start1 + k // 2 - 1 if start1 + k // 2 - 1 < len(nums1) else len(nums1) - 1
        mid2 = start2 + k // 2 - 1 if start2 + k // 2 - 1 < len(nums2) else len(nums2) - 1

        if nums1[mid1] > nums2[mid2]:
            return find_kth(nums1, mid1 + 1, nums2, start2, k - k // 2)
        else:
            return find_kth(nums1, start1, nums2, mid2 + 1, k - k // 2)

    return find_kth(list1, 0, list2, 0, k)

